{
  "packet_id": "H6-T02-2",
  "claim_id": "C066",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C066",
    "value": "Absence of rare delays is informative only with enough comparable exposure.",
    "scope": "A necessary exposure condition; the mapping does not quantify sufficient exposure or claim that exposure alone proves resolution.",
    "provenance": {
      "refs": [
        {
          "source_id": "P030",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly makes adequate comparable exposure necessary for informative absence."
    }
  },
  "signal_basis": {
    "component_id": "C066_signal_basis",
    "value": "A canary shows no rare delays during observation; evaluate that absence against a specified observation window and required comparable exposure, treating inadequate exposure or coverage as inconclusive.",
    "scope": "Interpretation of a clean canary observation, without treating a short clean run as establishing resolution.",
    "provenance": {
      "refs": [
        {
          "source_id": "P030",
          "role": "SUPPORT"
        },
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the clean-canary observation, exposure requirement, observation window and inconclusive-result qualification."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C066_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported within its stated limits; no unresolved empirical bridge is required."
    }
  },
  "rationale": "Rare delays can remain unobserved simply because too few comparable exports were observed. Requiring adequate comparable exposure before interpreting their absence is therefore warranted. The claim asserts a necessary condition, not proof of resolution.",
  "uncertainty": "The mapping does not quantify adequate exposure, so it cannot establish whether a particular clean run meets that condition. This does not undermine the stated necessary condition.",
  "anomalies": []
}
